-- =========================================================================
-- EduFit Demo Seed V1.39: dữ liệu demo số lượng lớn (chỉ profile dev, mật khẩu chung Password123@)
-- =========================================================================
-- Bổ sung cho V1.34, không sửa dữ liệu cũ. Mọi ID tường minh, đọc được theo số thứ tự:
--   Gia sư  tutor001..tutor100@edufit.vn     account 22222222-2222-2222-2222-1<NNN>, tutor_id 22222222-2222-2222-2222-2<NNN>
--   Học sinh student001..student080@edufit.vn account 11111111-1111-1111-1111-1<NNN>, student_id 11111111-1111-1111-1111-2<NNN>
--   Phụ huynh parent001..parent040@edufit.vn account 33333333-3333-3333-3333-1<NNN>
--   (<NNN> = số thứ tự đệm 0 đủ 11 chữ số, ví dụ tutor007 -> 22222222-2222-2222-2222-100000000007)
--   Gói dạy 88888888-8888-8888-<gia sư>-<thứ tự gói>, khung giờ 99999999-9999-9999-<gia sư>-<thứ tự>,
--   đánh giá aaaaaaaa-aaaa-aaaa-<gia sư>-<học sinh>, xác minh bbbbbbbb-..., liên kết phụ huynh cccccccc-...
--
-- PHÂN BỐ GIA SƯ (100):
--   001-050 Đà Nẵng (001-022 Ngũ Hành Sơn, 023-030 Hải Châu, 031-036 Sơn Trà, 037-041 Thanh Khê,
--           042-045 Cẩm Lệ, 046-048 Liên Chiểu, 049 Hòa Vang, 050 Quảng Nam cũ)
--   051-065 Hà Nội, 066-080 TP.HCM, 081-085 Huế, 086-089 Hải Phòng, 090-092 Cần Thơ, 093-094 Khánh Hòa,
--   095-096 Quảng Ngãi, 097-098 Nghệ An, 099-100 chỉ dạy online (không gắn tỉnh)
--   Trạng thái: 95 VERIFIED, 4 PENDING_VERIFICATION (050, 097, 098, 099), 1 UNVERIFIED bị từ chối (100).
--   tutor037 và tutor081 đã xác minh nhưng không có khung giờ rảnh (quy ước: kín lịch).
-- HỌC SINH (80): 40 Đà Nẵng (18 Ngũ Hành Sơn), 14 Hà Nội, 14 TP.HCM, 12 tỉnh khác; lớp 6-9.
-- PHỤ HUYNH (40): mỗi người liên kết (CONFIRMED) với 1-2 con cùng họ, cùng tỉnh; số học sinh còn lại tự học.
-- ĐÁNH GIÁ (953): theo nhóm gia sư
--   nổi bật 26-42 đánh giá (~4.8), tốt 8-20 (~4.3), trung bình 5-12 (~3.4), thấp 3-8 (~2.2),
--   mới 1-3 đánh giá (điểm lệch mạnh), chưa có đánh giá. Ngũ Hành Sơn có đủ mọi nhóm để demo sắp xếp và lọc.
--   Đánh giá chỉ nằm ở bảng review (không kèm lớp/buổi học); rating_avg, review_count tính lại từ bảng review.

CREATE FUNCTION pg_temp.prov(c TEXT) RETURNS INT AS $$ SELECT province_id FROM province WHERE code = c $$ LANGUAGE sql STABLE;
CREATE FUNCTION pg_temp.dist(c TEXT, d TEXT) RETURNS INT AS $$
    SELECT district_id FROM district WHERE province_id = pg_temp.prov(c) AND name = d
$$ LANGUAGE sql STABLE;
CREATE FUNCTION pg_temp.subj(n TEXT) RETURNS INT AS $$ SELECT subject_id FROM subject WHERE name = n $$ LANGUAGE sql STABLE;
CREATE FUNCTION pg_temp.track(c TEXT) RETURNS INT AS $$ SELECT track_id FROM subject_track WHERE code = c $$ LANGUAGE sql STABLE;
CREATE FUNCTION pg_temp.goal(c TEXT) RETURNS INT AS $$ SELECT goal_tag_id FROM goal_tag WHERE code = c $$ LANGUAGE sql STABLE;
CREATE FUNCTION pg_temp.book(c TEXT) RETURNS INT AS $$ SELECT series_id FROM textbook_series WHERE code = c $$ LANGUAGE sql STABLE;

