                           status, verified_at, rating_avg, review_count, tutor_type, tutor_type_verified, province_id,
                           created_at, updated_at)
SELECT v.tutor_id::uuid, v.user_id::uuid, v.display_name, v.headline, v.bio, v.mode, v.exp, v.method, v.status,
       CASE WHEN v.status = 'VERIFIED' THEN now() - make_interval(days => v.verified_age) END, NULL, 0,
       v.ttype, v.status = 'VERIFIED', pg_temp.prov(v.prov),
