     '3 năm dạy kèm Tiếng Anh cho học sinh THCS. Thế mạnh: ngữ pháp và từ vựng theo chủ đề và kỹ năng đọc hiểu và viết đoạn. Nhận lớp 1 kèm 1 hoặc nhóm nhỏ 2-3 bạn.', 'ONLINE', 3, 'Kết hợp bài giảng trực quan với đề kiểm tra định kỳ, báo tiến độ cho phụ huynh mỗi tháng.', 'PENDING_VERIFICATION', 'UNIVERSITY_STUDENT', NULL, 17, 17),
    ('22222222-2222-2222-2222-200000000100', '22222222-2222-2222-2222-100000000100', 'Thầy Trương Thành Tín', 'Giáo viên Tiếng Anh THCS · 12 năm đứng lớp · Dạy online',
     '12 năm giảng dạy Tiếng Anh cho học sinh THCS. Thế mạnh: luyện đề Cambridge theo từng kỹ năng và chiến lược làm bài thi chứng chỉ. Ưu tiên học sinh cần lộ trình rõ ràng, đều đặn.', 'ONLINE', 12, 'Sơ đồ tư duy cho từng chương, kiểm tra 15 phút đầu giờ để theo dõi tiến bộ.', 'UNVERIFIED', 'IN_SERVICE_TEACHER', NULL, 15, 15)
) AS v(tutor_id, user_id, display_name, headline, bio, mode, exp, method, status, ttype, prov, age, verified_age);

